async function build(sym,tf){const [k,h]=await Promise.all([klinesAny(sym,tf,320),HTF[tf]!==tf?klinesAny(sym,HTF[tf],120):Promise.resolve(null)]);return packet(sym,tf,k,h,h?HTF[tf]:'N/A');}
